    q("8", "من هو صانع ألعاب لوس أنجلوس ليكرز الذي سجل رمية الفوز الخالدة قبل 0.4 ثانية من نهاية مواجهة سبيرز 2004؟", "ديريك فيشر", "روبرت هوري", "كوبي براينت", "كارل مالون"),
    q("8", "كم ثانية كانت متبقية على لوحة النتائج عندما سجل ديريك فيشر سلته الإعجازية ضد سبيرز عام 2004؟", "0.4 ثانية", "0.8 ثانية", "0.2 ثانية", "0.6 ثانية"),
    q("8", "من هو اللاعب الملقب بـ \"Big Shot Bob\" الذي فاز بـ 7 ألقاب للـ NBA مع ثلاثة أندية مختلفة؟", "روبرت هوري", "ستيف كير", "جون باكسون", "ديريك فيشر"),
    q("8", "مع أي أندية حقق روبرت هوري ألقابه السبعة في دوري الـ NBA دون أن يخسر أي نهائي شارك به؟", "روكتس، ليكرز، وسبيرز", "بولز، سبيرز، وواريورز", "سلتكس، ليكرز، وبيستونز", "هيت، مافريكس، وروكتس"),
    q("8", "من هو المدافع الذي عرقل كوبي براينت في نهائي 2000 وتسبب في إصابته الشهيرة بالتواء الكاحل؟", "جالين روز", "ريجي ميلر", "مارك جاكسون", "ريك سميتس"),
    q("8", "كم نقطة سجل الأسطورة ريجي ميلر لإنديانا بيسرز في شباك نيويورك نيكس في غضون 8.9 ثوانٍ فقط (1995)؟", "8 نقاط", "9 نقاط", "7 نقاط", "10 نقاط"),
    q("8", "من هو المخرج السينمائي العالمي وأشهر مشجعي نيويورك نيكس الذي كان يستفزه ريجي ميلر دائماً على الخط؟", "سبايك لي", "مارتن سكورسيزي", "كوينتن تارانتينو", "وودي آلن"),
    q("8", "ما هي المباراة المشينة التي شهدت شجاراً جماهيرياً عنيفاً بين لاعبي إنديانا وديترويت عام 2004؟", "شجار القصر (Malice at the Palace)", "معركة ديترويت", "ليلة الشغب", "فوضى بالاس"),
    q("8", "من كان اللاعب الأبرز في إنديانا الذي عوقب بالإيقاف لبقية موسم 2004-2005 بسبب شجار القصر؟", "رون أرتيست (ميتا وورلد بيس)", "ستيفن جاكسون", "جيرمين أونيل", "جمال تينسلي"),
    q("8", "في أي عام ميلادي تغلب لوس أنجلوس ليكرز على غريمه التقليدي بوسطن سلتكس في نهائي من 7 مباريات ليتوج باللقب؟", "2010", "2009", "2011", "2008"),
    q("8", "من هو النجم الكرواتي الفائز بجائزة أفضل لاعب سادس في الـ NBA مع شيكاغو بولز في موسم 1995-1996 التاريخي؟", "توني كوكوتش", "درازان بيتروفيتش", "دينو رادجا", "زوران سافيتش"),
    q("8", "من هو النجم الكرواتي الأسطوري والمصنف كأحد أعظم المسددين في التاريخ الذي توفي بحادث سير عام 1993؟", "درازان بيتروفيتش", "توني كوكوتش", "دينو رادجا", "ستويكو فرانكوفيتش"),
    q("8", "مع أي فريق كان يلعب درازان بيتروفيتش عندما نال إشادة مايكل جوردن كأصعب مسدد واجهه بالـ NBA؟", "نيوجيرسي نتس", "بورتلاند تريل بليزرز", "بوسطن سلتكس", "نيويورك نيكس"),
    q("8", "من كان أول لاعب من الاتحاد السوفيتي يشارك في دوري الـ NBA في عام 1989 مع أتلانتا هوكس؟", "ألكسندر فولكوف", "شاروناس مارسيوليونيس", "أرفيداس سابونيس", "فاليري تيخونينكو"),
    q("8", "من هو لاعب الارتكاز الليتواني الأسطوري الذي دخل الـ NBA متأخراً مع بورتلاند عام 1995 في سن 31 عاماً؟", "أرفيداس سابونيس", "شاروناس مارسيوليونيس", "زيماس إيلغاوسكاس", "يوناس فالانتشيوناس"),
    q("8", "من هو نجم دالاس وسكرامنتو الصربي الذي فاز بلقب مسابقة الرميات الثلاثية لعامين متتاليين (2002 و2003)؟", "بيجا ستوياكوفيتش", "فلادي ديفاتش", "فلاديمير رادمانوفيتش", "ماركو ياريتش"),
  ];

  print("Total questions created: ${questions.length}");

  final Map<String, int> countsByLevel = {};
  for (final item in questions) {
    final lvl = item["Level"] as String;
    countsByLevel[lvl] = (countsByLevel[lvl] ?? 0) + 1;
  }

  print("Counts by level:");
  countsByLevel.keys.toList()..sort()..forEach((k) => print("  Level $k: ${countsByLevel[k]}"));

  final expected = {
    "0": 34,
    "1": 33,
    "2": 33,
    "4": 33,
    "5": 33,
    "6": 34,
    "3": 33,
    "7": 33,
    "8": 34,
  };

  expected.forEach((lvl, expectedCount) {
    final actual = countsByLevel[lvl] ?? 0;
    if (actual != expectedCount) {
      throw Exception("Level $lvl count mismatch: expected $expectedCount, got $actual");
    }
  });

  final tier0 = (countsByLevel["0"] ?? 0) + (countsByLevel["1"] ?? 0) + (countsByLevel["2"] ?? 0);
  final tier1 = (countsByLevel["4"] ?? 0) + (countsByLevel["5"] ?? 0) + (countsByLevel["6"] ?? 0);
  final tier2 = (countsByLevel["3"] ?? 0) + (countsByLevel["7"] ?? 0) + (countsByLevel["8"] ?? 0);
  print("Tier 0 total: $tier0 (expected 100)");
  print("Tier 1 total: $tier1 (expected 100)");
  print("Tier 2 total: $tier2 (expected 100)");

  assert(tier0 == 100);
  assert(tier1 == 100);
  assert(tier2 == 100);

  final Set<String> questionTexts = {};
  int leakCount = 0;
  for (int i = 0; i < questions.length; i++) {
    final qItem = questions[i];
    final qText = qItem["Q"] as String;
    final r = qItem["R"] as String;
    final w1 = qItem["W1"] as String;
    final w2 = qItem["W2"] as String;
    final w3 = qItem["W3"] as String;

    if (!qText.endsWith("؟")) {
      throw Exception("Question #$i does not end with '؟': $qText");
    }

    if (qText.contains("اكتب الرقم") || qText.contains("اختر") || qText.contains("ما رأيك")) {
      throw Exception("Question #$i contains forbidden phrase: $qText");
    }

    if (questionTexts.contains(qText)) {
      throw Exception("Duplicate question found at #$i: $qText");
    }
    questionTexts.add(qText);

    final set = {r, w1, w2, w3};
    if (set.length != 4) {
      throw Exception("Question #$i has duplicate options: R='$r', W1='$w1', W2='$w2', W3='$w3'");
    }

    // Leak check (R appearing inside Q):
    bool leak = false;
    if (r.length > 3 && qText.contains(r)) {
      leak = true;
    }
    if (leak) {
      print("Potential leak in #$i: Q='$qText' contains R='$r'");
      leakCount++;
    }
  }

  print("Total distinct questions: ${questionTexts.length}");
  print("Potential leaks: $leakCount");
  if (leakCount > 0) {
    throw Exception("Leaks found! Please resolve before continuing.");
  }

  // Write JSON to file
  final jsonStr = JsonEncoder.withIndent("  ").convert(questions);
  final outFile = File("assets/questions_nba_300.json");
  outFile.writeAsStringSync(jsonStr, encoding: utf8);
  print("Successfully saved 300 questions to ${outFile.path}");
}
